"use client";

import { useEffect, useState } from "react";
import { CHANNELS, CHANNEL_ORDER } from "@/lib/medjobs/activation";

/**
 * A custom task, with the manager's own checklist.
 *
 * Everything recurring is generated by the system, so this exists only for
 * the work the five channel workflows do not describe. No owner field: one
 * person runs this today, and an assignment picker with one name in it is
 * a control that teaches nothing.
 */
export default function NewTaskModal({
  onClose,
  onCreated,
}: {
  onClose: () => void;
  onCreated: () => void;
}) {
  const [universities, setUniversities] = useState<Array<{ id: string; slug: string; name: string }>>([]);
  const [campusId, setCampusId] = useState("");
  const [channel, setChannel] = useState("");
  const [title, setTitle] = useState("");
  const [dueAt, setDueAt] = useState(() => new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10));
  const [details, setDetails] = useState("");
  const [items, setItems] = useState<string[]>([""]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    void (async () => {
      const res = await fetch("/api/admin/medjobs/activation");
      if (!res.ok) return;
      const d = (await res.json()) as { universities: Array<{ id: string; slug: string; name: string }> };
      setUniversities(d.universities);
      if (d.universities[0]) setCampusId(d.universities[0].id);
    })();
  }, []);

  const submit = async () => {
    if (!title.trim() || !campusId) {
      setError("A task name and a university are required.");
      return;
    }
    setSaving(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/medjobs/activation/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          campusId,
          channel: channel || undefined,
          title: title.trim(),
          dueAt: new Date(`${dueAt}T12:00:00Z`).toISOString(),
          details: details.trim() || undefined,
          checklist: items.filter((t) => t.trim()).map((text) => ({ text: text.trim(), done: false })),
        }),
      });
      if (!res.ok) throw new Error("Failed");
      onCreated();
    } catch {
      setError("Could not create the task.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <div className="w-full max-w-md rounded-xl bg-white shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <header className="border-b border-gray-100 px-5 py-3">
          <h3 className="text-base font-semibold text-gray-900">New task</h3>
        </header>

        <div className="space-y-3 px-5 py-4">
          <Field label="Task">
            <input
              autoFocus
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full rounded-md border border-gray-200 px-2 py-1.5 text-sm focus:border-primary-400 focus:outline-none"
            />
          </Field>

          <div className="grid grid-cols-2 gap-3">
            <Field label="Due">
              <input
                type="date"
                value={dueAt}
                onChange={(e) => setDueAt(e.target.value)}
                className="w-full rounded-md border border-gray-200 px-2 py-1.5 text-sm focus:border-primary-400 focus:outline-none"
              />
            </Field>
            <Field label="University">
              <select
                value={campusId}
                onChange={(e) => setCampusId(e.target.value)}
                className="w-full rounded-md border border-gray-200 px-2 py-1.5 text-sm focus:border-primary-400 focus:outline-none"
              >
                {universities.map((u) => (
                  <option key={u.id} value={u.id}>
                    {u.name}
                  </option>
                ))}
              </select>
            </Field>
          </div>

          <Field label="Channel (optional)">
            <select
              value={channel}
              onChange={(e) => setChannel(e.target.value)}
              className="w-full rounded-md border border-gray-200 px-2 py-1.5 text-sm focus:border-primary-400 focus:outline-none"
            >
              <option value="">None</option>
              {CHANNEL_ORDER.map((c) => (
                <option key={c} value={c}>
                  {c.toUpperCase()} · {CHANNELS[c].name}
                </option>
              ))}
            </select>
          </Field>

          <Field label="Details">
            <textarea
              value={details}
              onChange={(e) => setDetails(e.target.value)}
              rows={2}
              className="w-full rounded-md border border-gray-200 px-2 py-1.5 text-sm focus:border-primary-400 focus:outline-none"
            />
          </Field>

          <Field label="Checklist">
            <div className="space-y-1.5">
              {items.map((v, i) => (
                <div key={i} className="flex gap-2">
                  <input
                    value={v}
                    onChange={(e) =>
                      setItems((prev) => prev.map((p, j) => (j === i ? e.target.value : p)))
                    }
                    onKeyDown={(e) => {
                      if (e.key === "Enter") setItems((prev) => [...prev, ""]);
                    }}
                    placeholder="What needs to be done"
                    className="min-w-0 flex-1 rounded-md border border-gray-200 px-2 py-1 text-[13px] focus:border-primary-400 focus:outline-none"
                  />
                  {items.length > 1 ? (
                    <button
                      type="button"
                      onClick={() => setItems((prev) => prev.filter((_, j) => j !== i))}
                      className="px-1 text-gray-400 hover:text-gray-600"
                      aria-label="Remove item"
                    >
                      ×
                    </button>
                  ) : null}
                </div>
              ))}
              <button
                type="button"
                onClick={() => setItems((prev) => [...prev, ""])}
                className="text-[12px] font-medium text-primary-700 hover:text-primary-800"
              >
                + Add item
              </button>
            </div>
          </Field>

          {error ? (
            <p className="rounded-md bg-red-50 px-2 py-1.5 text-[13px] text-red-700">{error}</p>
          ) : null}
        </div>

        <footer className="flex justify-end gap-2 border-t border-gray-100 px-5 py-3">
          <button onClick={onClose} className="rounded-md px-3 py-1.5 text-sm text-gray-600 hover:bg-gray-100">
            Cancel
          </button>
          <button
            onClick={() => void submit()}
            disabled={saving}
            className="rounded-md bg-primary-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-primary-700 disabled:opacity-50"
          >
            {saving ? "Creating…" : "Create"}
          </button>
        </footer>
      </div>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="block">
      <span className="mb-0.5 block text-[11px] font-semibold uppercase tracking-wide text-gray-500">
        {label}
      </span>
      {children}
    </label>
  );
}
